begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('11111111-1111-4111-8111-111111111111','author@onto.test'),('22222222-2222-4222-8222-222222222222','other@onto.test'),('33333333-3333-4333-8333-333333333333','reviewer@onto.test');
insert into onto.community_reviewers values('33333333-3333-4333-8333-333333333333');
insert into onto.community_venues(id,name,locality,region,latitude,longitude,timezone,service_region,evidence_url,verified_at) values('fixture-library','Public library','Middlebury','VT',44.0153,-73.1673,'America/New_York','vermont-corridor','https://example.org/fixture',now());
insert into onto.events(id,source_name,source_event_id,title,rating,starts_at) values('review-event','Fixture','event','Public event','general',now()+interval '1 day'),('family-event','Fixture','family','Children event','family',now()+interval '1 day');
insert into onto.apple_provider_tokens(user_id,encrypted_token) values('11111111-1111-4111-8111-111111111111','{"iv":"fixture","cipher":"encrypted-fixture"}');
create temp table test_ids(kind text primary key,id uuid);
grant all on test_ids to authenticated;
select ok(not has_table_privilege('authenticated','onto.apple_provider_tokens','SELECT'),'Apple revocation credentials are server-only');
select ok(not has_table_privilege('anon','onto.apple_provider_tokens','SELECT'),'Apple credentials are unavailable to guests');
select ok(not has_table_privilege('authenticated','onto.community_reviewers','INSERT'),'reviewer assignment is privileged');
select ok(not has_table_privilege('authenticated','onto.community_pilot','UPDATE'),'clients cannot activate submissions');
select ok(not has_table_privilege('authenticated','onto.hosted_submissions','UPDATE'),'clients cannot bypass host review');
select ok(not has_table_privilege('anon','onto.event_reviews','SELECT'),'private review authors are inaccessible to guests');
select is((select count(*) from information_schema.columns where table_schema='onto' and table_name='public_event_reviews'),4::bigint,'public review projection has exactly four non-identity fields');
select ok(not exists(select 1 from information_schema.columns where table_schema='onto' and table_name='public_event_reviews' and column_name in ('author_id','created_at','updated_at','user_id')),'no public review author or time');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select onto.submit_event_review('review-event',5,'Helpful')$$,'42501');
select throws_ok($$insert into onto.hosted_submissions(author_id,venue_id,title,description,meeting_instructions,starts_at,ends_at,category,state) values(auth.uid(),'fixture-library','Bypass','text','meet',now()+interval '1 day',now()+interval '2 days','games','approved')$$,'42501');
reset role;
update onto.community_pilot set hosting=true,reviews=true;
set local role authenticated;
select lives_ok($$insert into test_ids select 'host',onto.save_hosted_submission(null,jsonb_build_object('venue_id','fixture-library','title','Games','description','Public games','meeting_instructions','Meet at the public desk','starts_at',to_char(now()+interval '1 day','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'ends_at',to_char(now()+interval '1 day 2 hours','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'category','games','newcomers_welcome',true),true)$$,'author submits without approval');
select is((select count(*) from onto.events where source_name='onto community'),0::bigint,'pending host does not appear in catalog');
select throws_ok($$select onto.save_hosted_submission(null,jsonb_build_object('venue_id','fixture-library','title','Private home meetup','description','My house','meeting_instructions','Meet at my house','starts_at',to_char(now()+interval '1 day','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'ends_at',to_char(now()+interval '1 day 2 hours','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'category','games'),true)$$,'23514');
select throws_ok($$select onto.report_community_content('host',(select id from test_ids where kind='host'),'Pending must not be public')$$,'23514');
select throws_ok($$select onto.save_hosted_submission(null,jsonb_build_object('venue_id','fixture-library','title','Bad spin-off','description','Public games','meeting_instructions','Public desk','starts_at',to_char(now()+interval '1 day','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'ends_at',to_char(now()+interval '1 day 2 hours','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'category','games','parent_event_id','family-event'),true)$$,'23514');
select throws_ok($$select onto.submit_event_review('family-event',5,'Wrong scope')$$,'23514');
select lives_ok($$insert into test_ids select 'review',onto.submit_event_review('review-event',4,'Useful public instructions')$$,'author submits review');
select lives_ok($$select onto.submit_event_review('review-event',5,'Edited instructions')$$,'one review can be edited');
select is((select count(*) from onto.my_event_reviews()),1::bigint,'one active review per account and occurrence');
select is((select count(*) from onto.public_event_reviews),0::bigint,'pending review stays private');
select throws_ok($$select onto.moderate_community_content('host',(select id from test_ids where kind='host'),1,true,'approve')$$,'42501');
reset role;
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated","user_metadata":{"reviewer":true}}',true);
set local role authenticated;
select is((select count(*) from onto.my_hosted_submissions()),0::bigint,'other account cannot read private submissions');
select throws_ok($$select onto.cancel_hosted_submission((select id from test_ids where kind='host'))$$,'42501');
select throws_ok($$select onto.delete_event_review((select id from test_ids where kind='review'))$$,'42501');
select throws_ok($$select onto.moderate_community_content('host',(select id from test_ids where kind='host'),1,true,'spoof')$$,'42501');
reset role;
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select onto.moderate_community_content('host',(select id from test_ids where kind='host'),1,true,'Public venue verified')$$,'assigned reviewer approves host');
select lives_ok($$select onto.moderate_community_content('review',(select id from test_ids where kind='review'),2,true,'No identifying details')$$,'reviewer approves current review version');
select throws_ok($$select onto.moderate_community_content('review',(select id from test_ids where kind='review'),1,false,'stale')$$,'40001');
reset role;
set local role anon;
select is((select count(*) from onto.events where source_name='onto community'),1::bigint,'approved host publicly readable');
select is((select count(*) from onto.public_event_reviews),1::bigint,'approved review publicly readable');
select is((select body from onto.public_event_reviews),'Edited instructions','only approved content appears');
reset role;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select onto.report_community_content('host',(select id from test_ids where kind='host'),'Please check meeting instructions')$$,'signed-in explicit report works');
select is((select count(*) from onto.community_reports),0::bigint,'reporter cannot read private moderation records');
select lives_ok($$select onto.save_hosted_submission((select id from test_ids where kind='host'),jsonb_build_object('venue_id','fixture-library','title','Changed games','description','New public program','meeting_instructions','Meet at desk','starts_at',to_char(now()+interval '1 day','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'ends_at',to_char(now()+interval '1 day 2 hours','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'category','games'),true)$$,'material edit returns to review');
select is((select count(*) from onto.events where source_name='onto community'),0::bigint,'edited host is immediately withdrawn');
select lives_ok($$select onto.submit_event_review('review-event',3,'Changed review')$$,'edited review returns to review');
select is((select count(*) from onto.public_event_reviews),0::bigint,'edited review withdrawn');
reset role;
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select onto.moderate_community_content('host',(select id from test_ids where kind='host'),3,true,'Verified edit')$$,'reviewer approves edit');
select is((select count(*) from onto.community_reports),1::bigint,'assigned reviewer can inspect report');
select lives_ok($$select onto.resolve_community_report((select id from onto.community_reports limit 1))$$,'reviewer resolves report');
reset role;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select onto.delete_my_account('11111111-1111-4111-8111-111111111111')$$,'author can delete account');
reset role;
select is((select count(*) from onto.community_reports),0::bigint,'account deletion cascades reports');
select is((select count(*) from onto.event_reviews),0::bigint,'account deletion cascades private reviews');
select is((select count(*) from onto.hosted_submissions),0::bigint,'account deletion cascades private hosts');
select is((select count(*) from onto.events where source_name='onto community' and not is_cancelled),0::bigint,'account deletion withdraws published activities');
select is((select count(*) from onto.apple_provider_tokens),0::bigint,'account deletion cascades encrypted revocation material');
insert into auth.identities(id,provider_id,user_id,identity_data,provider) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','fixture-apple-subject','22222222-2222-4222-8222-222222222222','{"sub":"fixture-apple-subject"}','apple');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select onto.delete_my_account('22222222-2222-4222-8222-222222222222')$$,'55000','Apple-linked deletion requires provider revocation','database RPC cannot bypass Apple revocation');
reset role;
select ok(exists(select 1 from auth.users where id='22222222-2222-4222-8222-222222222222'),'blocked provider-bypass deletion preserves account');
select * from finish();
rollback;
